using Godot;
using GameUi=LibreKO.UiTheme;
namespace LibreKO.Editors.Desktop;
public static class Ui {
 public static readonly Color Accent=GameUi.Gold,Muted=GameUi.TextLo,Background=GameUi.Ink,Text=GameUi.TextHi;
 public static T Add<T>(Node parent,T child) where T:Node{parent.AddChild(child);return child;}
 public static Label Label(Node parent,string text,int size=13,Color? colour=null){var l=Add(parent,new Label{Text=text,MouseFilter=Control.MouseFilterEnum.Pass});l.AddThemeFontSizeOverride("font_size",size);l.AddThemeColorOverride("font_color",colour??Text);return l;}
 public static Label Heading(Node parent,string text,int size=20){var label=Label(parent,text,size);label.AddThemeFontOverride("font",GameUi.Strong);return label;}
 public static Button Button(Node parent,string text,Action action){var b=Add(parent,new Button{Text=text,CustomMinimumSize=new(0,28),MouseDefaultCursorShape=Control.CursorShape.PointingHand});b.Pressed+=action;return b;}
 public static Button IconButton(Node parent,string text,string icon,Action action){var b=Button(parent,text,action);b.Icon=LibreKO.UiIcons.Get(icon);b.ExpandIcon=true;b.AddThemeConstantOverride("icon_max_width",14);b.AddThemeConstantOverride("h_separation",6);return b;}
 public static LineEdit Input(Node parent,string placeholder="",string value=""){return Add(parent,new LineEdit{PlaceholderText=placeholder,Text=value,CustomMinimumSize=new(0,28),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});}
 public static LineEdit Field(Node parent,string title,string placeholder,string value=""){var column=Column(parent);Label(column,title,12,Muted);return Input(column,placeholder,value);}
 public static VBoxContainer Group(Node parent,string title){var panel=Add(parent,new PanelContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});panel.AddThemeStyleboxOverride("panel",Surface(8));var layout=Column(panel);layout.AddThemeConstantOverride("separation",6);var toggle=Button(layout,"▾  "+title.ToUpperInvariant(),()=>{});toggle.Alignment=HorizontalAlignment.Left;toggle.Flat=true;toggle.AddThemeFontSizeOverride("font_size",11);toggle.AddThemeFontOverride("font",GameUi.Strong);toggle.AddThemeColorOverride("font_color",Accent);toggle.AddThemeColorOverride("font_hover_color",GameUi.GoldBright);toggle.CustomMinimumSize=new(0,23);var body=Column(layout);body.AddThemeConstantOverride("separation",7);toggle.Pressed+=()=>{body.Visible=!body.Visible;toggle.Text=(body.Visible?"▾  ":"▸  ")+title.ToUpperInvariant();};return body;}
 public static string FieldName(string name)=>name switch{"Num"=>"Item ID","ReqLevel"=>"Required level","ReqIntel"=>"Required intelligence","MaxHpB"=>"HP bonus","MaxMpB"=>"MP bonus","Hitrate"=>"Hit rate","Evasionrate"=>"Evasion rate","Hp"=>"Health","Mp"=>"Mana","MapId"=>"Map ID","KnightCash"=>"Knight Cash (KC)","Authority"=>"Account role","PremiumDate"=>"Premium expiry","VipVaultExpiry"=>"VIP vault expiry",_=>System.Text.RegularExpressions.Regex.Replace(name,@"(?<=[a-z])(?=[A-Z])"," ")};
 public static string Section(LibreKO.Editors.Contracts.RecordKind kind,LibreKO.Editors.Contracts.FieldDescriptor field){
  var name=field.Name;if(kind==LibreKO.Editors.Contracts.RecordKind.Item){if(name is "Kind" or "Slot" or "Damage" or "MinDamage" or "MaxDamage" or "Delay" or "Range" or "Ac" or "Hitrate" or "Evasionrate" or "Duration")return "Combat & equipment";if(name is "Extension" or "ItemPlusId" or "ItemAlteration" or "ItemType")return "Upgrade & links";if(name.EndsWith("B"))return "Attribute bonuses";if(name.EndsWith("Damage")||name.EndsWith("Drain"))return "Elemental effects";if(name is "Effect1" or "Effect2")return "Item effects";}
  if(kind==LibreKO.Editors.Contracts.RecordKind.Character){if(name is "Level" or "Experience" or "StatPoints" or "Strength" or "Stamina" or "Dexterity" or "Intelligence" or "Magic" or "Hp" or "Mp")return "Level & attributes";if(name.StartsWith("Loyalty"))return "National points";if(name is "IsOnline" or "DeletionTime" or "LastOnlineTime" or "PlayMinutes" or "MonstersDefeated" or "PlayersDefeated" or "Deaths" or "UpdatedAt" or "Sealed")return "Session & statistics";}
  return field.Group;
 }
 public static StyleBoxFlat Surface(int margin=10,bool inset=false){var box=GameUi.WindowPanel(alpha:1);box.ShadowSize=0;box.BgColor=inset?new Color("111114"):new Color("1a1a1e");box.BorderColor=new Color("494238");box.SetContentMarginAll(margin);return box;}
 static StyleBoxFlat Box(Color bg,Color edge,int x=9,int y=5){var box=new StyleBoxFlat{BgColor=bg,BorderColor=edge};box.SetBorderWidthAll(1);box.SetCornerRadiusAll(2);box.ContentMarginLeft=box.ContentMarginRight=x;box.ContentMarginTop=box.ContentMarginBottom=y;return box;}
 public static void Primary(Button button){button.AddThemeStyleboxOverride("normal",Box(new("a78546"),GameUi.Gold,14,6));button.AddThemeStyleboxOverride("hover",Box(new("c8a45a"),GameUi.GoldBright,14,6));button.AddThemeStyleboxOverride("pressed",Box(new("796137"),GameUi.Gold,14,6));button.AddThemeStyleboxOverride("disabled",Box(new("302b22"),new("504735"),14,6));button.AddThemeColorOverride("font_color",new("17130c"));button.AddThemeColorOverride("font_hover_color",new("17130c"));button.AddThemeColorOverride("font_pressed_color",GameUi.TextHi);button.AddThemeColorOverride("font_disabled_color",new("8d8064"));button.AddThemeFontOverride("font",GameUi.Strong);}
 public static void Navigation(Button button,bool active){button.AddThemeStyleboxOverride("normal",GameUi.TopTab(active));button.AddThemeStyleboxOverride("hover",GameUi.TopTab(active,true));button.AddThemeStyleboxOverride("pressed",GameUi.TopTab(true));button.AddThemeColorOverride("font_color",active?GameUi.GoldBright:Muted);button.AddThemeColorOverride("font_hover_color",GameUi.GoldBright);button.AddThemeColorOverride("icon_normal_color",active?GameUi.Gold:Muted);}
 public static HBoxContainer Row(Node parent){var row=Add(parent,new HBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});row.AddThemeConstantOverride("separation",6);return row;}
 public static VBoxContainer Column(Node parent){var column=Add(parent,new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});column.AddThemeConstantOverride("separation",6);return column;}
 public static void Clear(Node parent){foreach(var c in parent.GetChildren()){parent.RemoveChild(c);c.QueueFree();}}
 public static Theme Theme(){
  var t=(Theme)LibreKO.HudTheme.Shared.Duplicate(true);t.DefaultFont=new SystemFont{FontNames=["Segoe UI","Arial"]};t.DefaultFontSize=13;
  foreach(var type in new[]{"PanelContainer","Panel","PopupPanel"})t.SetStylebox("panel",type,Surface());
  t.SetColor("font_color","Label",Text);t.SetColor("font_shadow_color","Label",new(0,0,0,0));
  t.SetStylebox("normal","Button",Box(new("242326"),new("514b40")));t.SetStylebox("hover","Button",Box(new("302b24"),GameUi.Bronze));t.SetStylebox("pressed","Button",Box(new("171619"),GameUi.GoldDark));t.SetStylebox("disabled","Button",Box(new("1b1a1c"),new("373431")));
  t.SetStylebox("focus","Button",Box(new(0,0,0,0),GameUi.Gold,0,0));t.SetFontSize("font_size","Button",12);
  t.SetColor("font_color","Button",Text);t.SetColor("font_hover_color","Button",GameUi.GoldBright);t.SetColor("font_pressed_color","Button",GameUi.GoldBright);t.SetColor("font_disabled_color","Button",new("77716a"));
  foreach(var type in new[]{"Button","OptionButton"}){t.SetColor("icon_normal_color",type,GameUi.Gold);t.SetColor("icon_hover_color",type,GameUi.GoldBright);t.SetColor("icon_disabled_color",type,Muted);}
  foreach(var type in new[]{"LineEdit","TextEdit"}){t.SetStylebox("normal",type,Box(new("111114"),new("3e3b36"),8,5));t.SetStylebox("read_only",type,Box(new("19181a"),new("302e2a"),8,5));t.SetStylebox("focus",type,Box(new(0,0,0,0),GameUi.Gold,0,0));t.SetColor("font_color",type,Text);t.SetColor("font_uneditable_color",type,new("a8a298"));t.SetColor("font_readonly_color",type,Muted);t.SetColor("font_placeholder_color",type,new("7b766d"));t.SetColor("caret_color",type,GameUi.Gold);t.SetColor("selection_color",type,new("5a4b30"));}
  foreach(var type in new[]{"ItemList","Tree"}){t.SetStylebox("panel",type,Surface(4,true));t.SetStylebox("selected",type,Box(new("393123"),new("80653a"),4,3));t.SetStylebox("selected_focus",type,Box(new("393123"),GameUi.GoldDark,4,3));t.SetStylebox("hovered",type,Box(new("27241f"),new("4f4534"),4,3));t.SetStylebox("focus",type,new StyleBoxEmpty());t.SetColor("font_color",type,Text);t.SetColor("font_selected_color",type,GameUi.GoldBright);t.SetConstant("v_separation",type,8);t.SetConstant("h_separation",type,8);}
  foreach(var type in new[]{"TabBar","TabContainer"}){t.SetStylebox("tab_selected",type,GameUi.TopTab(true));t.SetStylebox("tab_unselected",type,GameUi.TopTab(false));t.SetStylebox("tab_hovered",type,GameUi.TopTab(false,true));t.SetColor("font_selected_color",type,GameUi.GoldBright);t.SetColor("font_unselected_color",type,Muted);t.SetColor("font_hovered_color",type,Text);t.SetFontSize("font_size",type,12);}
  t.SetStylebox("panel","TabContainer",new StyleBoxEmpty());t.SetStylebox("panel","PopupMenu",Surface(6));t.SetStylebox("hover","PopupMenu",Box(new("393123"),GameUi.GoldDark,4,4));t.SetColor("font_color","PopupMenu",Text);t.SetColor("font_hover_color","PopupMenu",GameUi.GoldBright);
  t.SetStylebox("panel","AcceptDialog",Surface(10));t.SetStylebox("panel","ConfirmationDialog",Surface(10));var window=Surface(10);window.BorderColor=GameUi.Bronze;window.ContentMarginTop=30;t.SetStylebox("embedded_border","Window",window);t.SetStylebox("embedded_unfocused_border","Window",window);t.SetColor("title_color","Window",GameUi.GoldBright);t.SetFontSize("title_font_size","Window",14);
  t.SetStylebox("panel","TooltipPanel",Surface(8,true));t.SetColor("font_color","TooltipLabel",Text);t.SetFontSize("font_size","TooltipLabel",12);
  foreach(var type in new[]{"HSplitContainer","VSplitContainer"})t.SetConstant("separation",type,10);
  return t;
 }
}
